    var context: TemplateScreenViewModelType.Context {
        viewModel.context
    }

    init() {
        viewModel = TemplateScreenViewModel()
    }

    @Test
    func initialState() {
        #expect(!context.composerText.isEmpty)
        #expect(context.viewState.counter == 0)
    }

