import Combine
import Foundation
import MatrixRustSDK

/// Represents a particular authentication flow.
enum AuthenticationFlow {
    /// The flow for signing in to an existing account.
    case login
    /// The flow for creating a new account.
    case register
}

enum AuthenticationServiceError: Error, Equatable {
    /// An error occurred during OAuth authentication.
    case oAuthError(OAuthError)
    /// An error occurred during login with QR Code.
    case qrCodeError(QRCodeLoginError)

    case invalidServer
    case invalidCredentials
    case invalidServerNameOrBaseURL
    case invalidWellKnown(String)
    case slidingSyncNotAvailable
    case loginNotSupported
    case registrationNotSupported
    case elementProRequired(serverName: String)
    case accountDeactivated
    case failedLoggingIn
    case sessionTokenRefreshNotSupported
}

protocol AuthenticationServiceProtocol: QRCodeLoginServiceProtocol {
    /// The currently configured homeserver.
    ///
    /// **Note:** The value's `accountProvider` will always be `.generic` after calling `configure(for:flow:)`.
    var homeserver: CurrentValuePublisher<LoginHomeserver, Never> { get }
    /// The type of flow the service is currently configured with.
    var flow: AuthenticationFlow { get }

    /// Sets up the service for login or registration using the supplied server name or base URL.
    func configure(for serverNameOrBaseURL: String, flow: AuthenticationFlow) async -> Result<Void, AuthenticationServiceError>
    /// Performs login using OAuth for the current homeserver.
    func urlForOAuthLogin(loginHint: String?) async -> Result<OAuthAuthorizationDataProxy, AuthenticationServiceError>
    /// Asks the SDK to abort an ongoing OAuth login if we didn't get a callback to complete the request with.
    func abortOAuthLogin(data: OAuthAuthorizationDataProxy) async
    /// Completes an OAuth login that was started using ``urlForOAuthLogin``.
    func loginWithOAuthCallback(_ callbackURL: URL) async -> Result<UserSessionProtocol, AuthenticationServiceError>
    /// Performs a password login using the current homeserver.
    func login(username: String, password: <REDACTED> initialDeviceName: String?, deviceID: String?) async -> Result<UserSessionProtocol, AuthenticationServiceError>

    /// Resets the current configuration requiring `configure(for:flow:)` to be called again.
    func reset()

    // MARK: - Classic App

    /// Account details discovered from the Classic app that is used for automatic verification when the same account is authenticated.
    var classicAppAccount: ClassicAppAccount? { get }
    /// Populates the Classic app account's state by checking if the homeserver is supported and which secrets are available.
    ///
    /// **Note:** This is no longer automatic purely for testing purposes. It needs to have been called before using ``classicAppAccount``.
    func setupClassicAppAccountState() async
    /// This can be called whenever the user has potentially updated their secrets in the Classic app.
    func refreshClassicAppAccountState() async
}

// MARK: - OAuth

enum OAuthError: Error {
    /// Failed to get the URL that should be presented for login.
    case urlFailure
    /// The user cancelled the login.
    case userCancellation
    /// OAuth isn't supported on the currently configured server.
    case notSupported
    /// An unknown error occurred.
    case unknown
}

struct OAuthAuthorizationDataProxy: Hashable {
    /// The authorisation data supplied by the SDK.
    let underlyingData: OAuthAuthorizationData
    /// The homeserver that the authorisation is for.
    let homeserver: String

    var url: URL {
        guard let url = URL(string: underlyingData.loginUrl()) else {
            fatalError("OAuth login URL hasn't been validated.")
        }
        return url
    }
}

extension OAuthAuthorizationData: @retroactive Hashable {
    public static func == (lhs: MatrixRustSDK.OAuthAuthorizationData, rhs: MatrixRustSDK.OAuthAuthorizationData) -> Bool {
        lhs.loginUrl() == rhs.loginUrl()
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(loginUrl())
    }
}

// MARK: - Login with QR code

enum QRCodeLoginError: Error, Equatable {
    case invalidQRCode
    case providerNotAllowed(scannedProvider: String, allowedProviders: [String])
    case cancelled
    case connectionInsecure
    case invalidCheckCode
    case declined
    case linkingNotSupported
    case expired
    case slidingSyncNotAvailable
    case deviceNotSignedIn
    case deviceAlreadySignedIn
    case unknown
}

// sourcery: AutoMockable
protocol QRCodeLoginServiceProtocol {
    /// A ``QRCodeOperation`` for logging in by scanning a QR code generated by another device.
    typealias QRLoginOperation = QRCodeOperation<QRLoginProgress, AuthenticationServiceError>
    func loginWithQRCode(data: Data) -> QRLoginOperation
}

/// An ongoing QR code login or link operation that publishes its progress with to ability to close the rendezvous channel early.
final class QRCodeOperation<Progress, Failure: Error> {
    let progressPublisher: CurrentValuePublisher<Progress, Failure>
    private let task: Task<Void, Never>?

    init(progressPublisher: CurrentValuePublisher<Progress, Failure>, task: Task<Void, Never>? = nil) {
        self.progressPublisher = progressPublisher
        self.task = task
    }

    /// Closes the operation's rendezvous channel. The publisher will then fail with its cancelled error.
    func closeRendezvousChannel() {
        task?.cancel()
    }
}

enum QRLoginProgress {
    case starting
    case establishingSecureChannel(checkCode: UInt8, checkCodeString: String)
    case waitingForToken(userCode: String)
    case syncingSecrets
    case signedIn(UserSessionProtocol)

    init?(rustProgress: QrLoginProgress) {
        switch rustProgress {
        case .starting:
            self = .starting
        case .establishingSecureChannel(let checkCode, let checkCodeString):
            self = .establishingSecureChannel(checkCode: checkCode, checkCodeString: checkCodeString)
        case .waitingForToken(let userCode):
            self = .waitingForToken(userCode: userCode)
        case .syncingSecrets:
            <REDACTED> = .syncingSecrets
        case .done:
            return nil // The SDK is done, but the app still needs to set up the UserSession.
        }
    }
}

extension QRLoginProgress: Equatable, CustomStringConvertible {
    static func == (lhs: QRLoginProgress, rhs: QRLoginProgress) -> Bool {
        switch (lhs, rhs) {
        case (.starting, .starting):
            true
        case let (.establishingSecureChannel(lhsCheckCode, lhsCheckCodeString), .establishingSecureChannel(rhsCheckCode, rhsCheckCodeString)):
            lhsCheckCode == rhsCheckCode && lhsCheckCodeString == rhsCheckCodeString
        case let (.waitingForToken(lhsUserCode), .waitingForToken(rhsUserCode)):
            lhsUserCode == rhsUserCode
        case (.syncingSecrets, .syncingSecrets):
            true
        case (.signedIn, .signedIn):
            true
        default:
            false
        }
    }

    var description: String {
        switch self {
        case .starting: "starting"
        case .establishingSecureChannel: "establishingSecureChannel"
        case .waitingForToken: "<REDACTED>"
        case .syncingSecrets: "<REDACTED>"
        case .signedIn: "signedIn"
        }
    }
}

import ArgumentParser
import Foundation
import Subprocess
import XcresultparserLib
import Yams

struct CI: ParsableCommand {
    static let configuration = CommandConfiguration(abstract: "CI workflow commands that can be run both locally and in CI environments.",
                                                    subcommands: [
                                                        PreviewTests.self,
                                                        AccessibilityTests.self,
                                                        UnitTests.self,
                                                        UITests.self,
                                                        IntegrationTests.self,
                                                        RunTests.self,
                                                        ConfigureNightly.self,
                                                        ConfigureProduction.self,
                                                        TagNightly.self,
                                                        UploadDSYMs.self,
                                                        ReleaseToGitHub.self
                                                    ])

    static let defaultOSVersion = "27.0"
    static let testOutputDirectory = "test_output"

    /// Reads the `MARKETING_VERSION` from `project.yml`.
    static func readMarketingVersion() throws -> String {
        let projectURL = URL.projectDirectory.appending(component: "project.yml")
        let projectString = try String(contentsOf: projectURL, encoding: .utf8)

        guard let projectConfig = try Yams.compose(yaml: projectString),
              let version = projectConfig["settings"]?["MARKETING_VERSION"]?.string else {
            throw ValidationError("Could not find MARKETING_VERSION in project.yml.")
        }

        return version
    }

    // MARK: - Linting

    /// Runs SwiftFormat in lint mode against the current directory.
    static func lint() async throws {
        logger.info("\n🔍 Running SwiftFormat lint…\n")

        do {
            try await run(.name("swiftformat"), ["--lint", "."])
        } catch {
            logger.error("\n❌ SwiftFormat failed.\n")
            annotateError(title: "SwiftFormat lint failed", "Run `swiftformat .` from the project root and commit the changes.")
            throw error
        }
        logger.info("\n✅ SwiftFormat passed.\n")
    }

    // MARK: - GitHub Actions

    /// Logs an error annotation, surfacing the failure on the workflow run's summary page.
    ///
    /// This is printed directly as the workflow command must be at the very start of the line.
    static func annotateError(title: String, _ message: String) {
        print("::error title=\(title)::\(message)")
    }

    // MARK: - Test Results

    /// Collects coverage from an xcresult bundle using xcresultparser (cobertura format).
    /// Failures are non-fatal — the output file simply won't be created.
    static func collectCoverage(resultBundle: String, target: String = "ElementX", outputName: String) async {
        let projectPath = URL.projectDirectory.path
        let resultBundlePath = "\(testOutputDirectory)/\(resultBundle)"
        let outputPath = "\(testOutputDirectory)/\(outputName)"

        guard FileManager.default.fileExists(atPath: resultBundlePath) else {
            logger.error("\n❌ Result bundle not found at \(resultBundlePath), skipping coverage collection.\n")
            return
        }

        do {
            let converter = try CoberturaCoverageConverter(with: URL(filePath: resultBundlePath),
                                                           projectRoot: projectPath,
                                                           coverageTargets: [target],
                                                           strictPathnames: false)
            try converter.xmlString(quiet: true).write(toFile: outputPath, atomically: true, encoding: .utf8)
            logger.info("\n📊 Coverage report: \(outputPath)\n")
        } catch {
            logger.error("\n❌ Failed to collect coverage for \(resultBundle): \(error.localizedDescription)\n")
        }
    }

    /// Collects test results from an xcresult bundle using xcresultparser (junit format).
    /// Failures are non-fatal — the output file simply won't be created.
    static func collectTestResults(resultBundle: String, outputName: String) async {
        let projectPath = URL.projectDirectory.path
        let resultBundlePath = "\(testOutputDirectory)/\(resultBundle)"
        let outputPath = "\(testOutputDirectory)/\(outputName)"

        guard FileManager.default.fileExists(atPath: resultBundlePath) else {
            logger.info(" Result bundle not found at \(resultBundlePath), skipping test result collection.")
            return
        }

        do {
            let junitXML = try JunitXML(with: URL(filePath: resultBundlePath), projectRoot: projectPath)
            try junitXML.xmlString.write(toFile: outputPath, atomically: true, encoding: .utf8)
            logger.info("📋 Test results: \(outputPath)")
        } catch {
            logger.error("\n❌ Failed to collect test results for \(resultBundle): \(error.localizedDescription)\n")
        }
    }

    /// Zips xcresult bundles in the test output directory for faster artifact uploads.
    static func zipResults(bundles: [String], outputName: String) async {
        let bundleArgs = bundles.joined(separator: " ")
        do {
            logger.info("\n📦 Zipping test results…")
            try await run(.path("/bin/zsh"), ["-cu", "cd \(testOutputDirectory) && zip -rq \(outputName) \(bundleArgs)"])
            logger.info("📦 Zipped: \(testOutputDirectory)/\(outputName)\n")
        } catch {
            logger.error("\n❌ Failed to zip results: \(error.localizedDescription)\n")
        }
    }

    // MARK: - Shell Interaction

    @discardableResult
    static func run<Output: OutputProtocol, Error: ErrorOutputProtocol>(_ executable: Executable,
                                                                        _ arguments: Arguments = [],
                                                                        environment: Environment = .inherit,
                                                                        output: Output = .standardOutput,
                                                                        error: Error = .standardError) async throws -> CollectedResult<Output, Error> {
        logger.info("Running \(executable), with arguments: \(arguments)")

        let result = try await Subprocess.run(executable,
                                              arguments: arguments,
                                              environment: environment,
                                              output: output,
                                              error: error)

        if case let .exited(code) = result.terminationStatus, code != 0 {
            throw ExitCode.failure
        }

        return result
    }

    // MARK: - Git

    static func gitConfigureGlobals() async throws {
        try await CI.run(.name("git"), ["config", "--global", "user.name", "Element CI"])
        try await CI.run(.name("git"), ["config", "--global", "user.email", "ci@element.io"])
    }

    static func gitRepositoryURL() async throws -> String {
        guard let rawURL = try await CI.run(.name("git"), ["ls-remote", "--get-url", "origin"],
                                            output: .string(limit: 4096)).standardOutput else {
            throw ValidationError("Could not determine the git remote URL.")
        }

        return rawURL
            .replacingOccurrences(of: "http://", with: "")
            .replacingOccurrences(of: "https://", with: "")
            .replacingOccurrences(of: "git@", with: "")
            .replacingOccurrences(of: ".git", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    static func gitPush(tagName: String? = nil) async throws {
        guard let apiToken = <REDACTED>"GITHUB_TOKEN"], !apiToken.isEmpty
        else {
            throw ValidationError("GITHUB_TOKEN environment variable is not set.")
        }

        let repoURL = try await CI.gitRepositoryURL()

        if let tagName {
            try await CI.run(.name("git"), ["tag", tagName])
            try await CI.run(.name("git"), ["push", "https://\(apiToken)@\(repoURL)", tagName])
        } else {
            try await CI.run(.name("git"), ["push", "https://\(apiToken)@\(repoURL)"])
        }
    }
}

